<?php /* VIVA NOTE: Chat inbox with links to booking-scoped conversations. */ ?><div class="toolbar"><p>Conversations linked to your student booking requests.</p></div><section class="panel">
<?php foreach($threads as $t):?><a class="thread" href="<?=e(url('/chat',['id'=>$t['conversation_id']]))?>"><span class="avatar"><?=e(mb_strtoupper(mb_substr($t['student_name'],0,1)))?></span><span><strong><?=e($t['student_name'])?></strong><small><?=e($t['last_message_at']?date_label($t['last_message_at']):'Start conversation')?></small></span><?php if((int)$t['unread']>0):?><span class="unread"><?=e($t['unread'])?></span><?php endif;?></a><?php endforeach;?>
<?php if(!$threads):?><div class="empty">No conversations yet. Open a booking and select “Message this student”.</div><?php endif;?></section>
